css:
@media print {
	@page {
		size: A4;
		margin: 15mm;
	}

	.page-break {
		page-break-after: always;
	}

	.no-print {
		display: none;
	}
}

.issue-order-standard {
	font-family: 'Segoe UI', 'Arial', sans-serif;
	font-size: 11pt;
	color: #2c3e50;
	max-width: 210mm;
	margin: 0 auto;
	background: white;
	padding: 0;
	line-height: 1.4;
}

/* Заголовок */
.header-section {
	padding: 12px 25px;
	margin-bottom: 20px;
	border-bottom: 3px solid #2c3e50;
	background: white;
}

.header-content {
	position: relative;
	display: flex;
	justify-content: space-between;
	align-items: center;
}

.doc-title {
	font-size: 16pt;
	font-weight: 700;
	margin: 0;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	color: #2c3e50;
}

.doc-meta {
	display: flex;
	align-items: center;
	gap: 15px;
}

.doc-number {
	font-size: 12pt;
	font-weight: 700;
	color: #2c3e50;
}

.status-badge {
	padding: 4px 10px;
	border-radius: 3px;
	font-weight: 600;
	font-size: 9pt;
	text-transform: uppercase;
	letter-spacing: 0.3px;
	border: 1px solid currentColor;
}

.status-draft {
	background: #fff8e1;
	color: #f57c00;
	border-color: #f57c00;
}

.status-submitted {
	background: #e8f5e9;
	color: #2e7d32;
	border-color: #2e7d32;
}

.status-cancelled {
	background: #ffebee;
	color: #c62828;
	border-color: #c62828;
}

/* Основний контент */
.content-section {
	padding: 0 25px;
}

/* Інформаційні картки */
.info-card {
	background: white;
	border: 1px solid #dee2e6;
	padding: 12px 15px;
	margin-bottom: 15px;
}

.info-card-title {
	font-size: 10pt;
	font-weight: 700;
	color: #2c3e50;
	margin-bottom: 10px;
	text-transform: uppercase;
	letter-spacing: 0.3px;
	border-bottom: 1px solid #dee2e6;
	padding-bottom: 6px;
}

.info-grid {
	display: grid;
	grid-template-columns: repeat(2, 1fr);
	gap: 12px;
}

.info-item {
	display: flex;
	align-items: baseline;
	gap: 8px;
}

.info-label {
	font-weight: 600;
	color: #555;
	font-size: 10pt;
	min-width: 120px;
}

.info-value {
	color: #2c3e50;
	font-size: 10pt;
	flex: 1;
}

/* Рішення-підстава */
.decision-box {
	background: white;
	border: 1px solid #dee2e6;
	padding: 12px 15px;
	margin: 15px 0;
}

.decision-box strong {
	color: #2c3e50;
	font-size: 10pt;
}

.decision-info {
	margin-top: 6px;
	font-size: 9pt;
	color: #6c757d;
}

.decision-info span {
	margin-right: 15px;
	font-weight: 600;
}

/* Таблиця активів */
.section-header {
	background: #2c3e50;
	color: white;
	padding: 8px 15px;
	margin: 20px 0 10px 0;
	font-size: 11pt;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.5px;
}

.items-table {
	width: 100%;
	border-collapse: separate;
	border-spacing: 0;
	margin: 12px 0;
	font-size: 10pt;
	border: 1px solid #dee2e6;
	border-radius: 4px;
	overflow: hidden;
}

.items-table thead {
	background: #5e72e4;
	color: white;
}

.items-table th {
	padding: 12px 10px;
	text-align: left;
	font-weight: 700;
	font-size: 9pt;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	border: none;
    color: black;
}

.items-table tbody tr {
	border-bottom: 1px solid #e9ecef;
}

.items-table tbody tr:nth-child(even) {
	background-color: #f8f9fa;
}

.items-table td {
	padding: 10px;
	vertical-align: middle;
	color: #2c3e50;
	border: none;
}

.items-table tfoot {
	background: #e9ecef;
	font-weight: 700;
	border-top: 3px solid #5e72e4;
}

.items-table tfoot td {
	padding: 12px 10px;
	color: #2c3e50;
	font-size: 11pt;
}

.text-right {
	text-align: right;
}

.text-center {
	text-align: center;
}

/* Підсумки */
.totals-box {
	background: #5e72e4;
	color: white;
	padding: 15px 20px;
	margin: 18px 0;
	border-radius: 4px;
	border: 3px solid #324cdd;
}

.total-amount {
	font-size: 16pt;
	font-weight: 700;
	text-align: right;
	margin-bottom: 5px;
}

.total-words {
	font-size: 10pt;
	text-align: right;
	opacity: 0.9;
	font-style: italic;
}

/* Підписи */
.signatures-section {
	margin-top: 40px;
	display: grid;
	grid-template-columns: repeat(2, 1fr);
	gap: 40px;
}

.signature-box {
	padding: 0;
}

.signature-label {
	font-weight: 700;
	color: #2c3e50;
	font-size: 10pt;
	margin-bottom: 50px;
}

.signature-line {
	border-top: 1px solid #2c3e50;
	padding-top: 5px;
	color: #6c757d;
	font-size: 9pt;
	text-align: center;
}

/* Футер */
.footer-section {
	margin-top: 40px;
	padding: 10px 25px;
	border-top: 1px solid #dee2e6;
	text-align: center;
	font-size: 8pt;
	color: #999;
}

/* Іконки */
.icon {
	display: inline-block;
	width: 16px;
	height: 16px;
	margin-right: 5px;
	vertical-align: middle;
}

/* Пуста таблиця */
.empty-state {
	text-align: center;
	padding: 40px 20px;
	background: #f8f9fa;
	border: 2px dashed #cbd5e0;
	border-radius: 8px;
	color: #6c757d;
	font-size: 11pt;
}

.empty-state-icon {
	font-size: 48pt;
	opacity: 0.3;
	margin-bottom: 10px;
}

@media print {
	.header-section {
		-webkit-print-color-adjust: exact;
		print-color-adjust: exact;
	}

	.items-table thead {
		-webkit-print-color-adjust: exact;
		print-color-adjust: exact;
	}

	.totals-box {
		-webkit-print-color-adjust: exact;
		print-color-adjust: exact;
	}
}
